import{_ as e,o as l,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Developer Monthly 2021-08-04","description":"","frontmatter":{"title":"Ceph Developer Monthly 2021-08-04","date":"2021-08-04T00:00:00.000Z","updated":"2021-08-24T00:00:00.000Z","tags":["Ceph Dashboard","GSoC 实习生项目","Ceph 开发者会议","Ceph 性能优化","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Developer_Monthly_2021-08-04.md","filePath":"posts/2021/Ceph_Developer_Monthly_2021-08-04.md","lastUpdated":1780460162000}'),i={name:"posts/2021/Ceph_Developer_Monthly_2021-08-04.md"};function h(t,a,s,n,d,p){return l(),r("div",null,[...a[0]||(a[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-dashboard-团队-gsoc-实习生项目汇报" tabindex="-1">会议主题：Ceph Dashboard 团队 GSoC 实习生项目汇报 <a class="header-anchor" href="#会议主题-ceph-dashboard-团队-gsoc-实习生项目汇报" aria-label="Permalink to &quot;会议主题：Ceph Dashboard 团队 GSoC 实习生项目汇报&quot;">​</a></h4><h4 id="参会人员-shreya-sharma-gsoc-实习生-dashboard-团队-、aryan-gsoc-实习生-dashboard-团队-、其他团队成员" tabindex="-1">参会人员：Shreya Sharma（GSoC 实习生，Dashboard 团队）、Aryan（GSoC 实习生，Dashboard 团队）、其他团队成员 <a class="header-anchor" href="#参会人员-shreya-sharma-gsoc-实习生-dashboard-团队-、aryan-gsoc-实习生-dashboard-团队-、其他团队成员" aria-label="Permalink to &quot;参会人员：Shreya Sharma（GSoC 实习生，Dashboard 团队）、Aryan（GSoC 实习生，Dashboard 团队）、其他团队成员&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>Shreya Sharma 的项目汇报</strong></p><ul><li>提出从 Ceph Dashboard 和 CLI 直接报告问题的功能，以提高用户报告问题的便利性和响应率。</li><li>使用 Thor Requests 库，并通过 Ceph 问题跟踪器的 API 密钥进行身份验证。</li><li>支持通过 CLI 和 Dashboard UI 报告问题，并计划支持附加图像、从文件中提供描述等功能。</li></ul></li><li><p><strong>Aryan 的项目汇报</strong></p><ul><li>开发 Ceph Dashboard 的视觉回归测试，以捕捉 CSS 错误和框架升级带来的视觉变化。</li><li>使用 Amplitude 工具进行视觉回归测试。</li><li>计划编写更多测试用例，完善 CI/CD 管道集成，并编写文档以帮助贡献者。</li></ul></li><li><p><strong>Ceph Manager 性能优化</strong></p><ul><li>针对 Manager 模块性能问题进行优化，包括 API 方法暴露、基准测试和多线程。</li><li>使用 JSON 格式和缓存策略提高性能。</li><li>计划进一步优化性能测试和数据格式。</li></ul></li><li><p><strong>Jaeger 跟踪</strong></p><ul><li>讨论使用 Jaeger 进行分布式跟踪的计划，以及如何通过跟踪来改进多站点和复杂操作的调试。</li><li>计划实现可配置的跟踪选项，以适应不同场景。</li></ul></li><li><p><strong>崩溃报告</strong></p><ul><li>介绍新的崩溃报告仪表板和崩溃报告机器人，用于跟踪和关联崩溃事件。</li><li>计划进一步开发崩溃报告功能，以提高系统的可观察性和调试能力。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续推进视觉回归测试和问题报告功能的开发。</li><li>探索更高效的性能测试和数据处理方法。</li><li>开始实施 Jaeger 跟踪，并探索更高效的性能测试方法。</li><li>开发新的崩溃报告功能。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>Shreya Sharma 将继续完善问题报告功能，并探索附加图像和文件描述的支持。</li><li>Aryan 将继续编写更多视觉回归测试用例，并完善 CI/CD 集成。</li><li>团队将开始实施 Jaeger 跟踪，并探索更高效的性能测试方法。</li><li>开发新的崩溃报告功能。</li></ul><h4 id="其他备注" tabindex="-1">其他备注： <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注：&quot;">​</a></h4><ul><li>讨论了安全性和隐私问题，特别是如何在不牺牲安全性的前提下简化用户报告问题的流程。</li><li>强调了自动化性能测试和数据处理方法的重要性，以及如何通过改进数据格式和缓存策略来提高性能。</li></ul>',12)])])}const _=e(i,[["render",h]]);export{c as __pageData,_ as default};
